def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by_distance(src, items, mode="min"):
        best_item = None
        best_score = None
        for it in items or []:
            p = pos(it, None)
            if p is None:
                continue
            score = manhattan(src, p)
            if best_item is None or (mode == "min" and score < best_score) or (mode == "max" and score > best_score):
                best_item = p
                best_score = score
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_role = observation.get("self_role", "pursuer")

    if env == "pursuit_evasion":
        if self_role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        grid_w = observation.get("grid_width")
        grid_h = observation.get("grid_height")
        corners = []
        if isinstance(grid_w, int) and isinstance(grid_h, int) and grid_w > 0 and grid_h > 0:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        else:
            corners = [(sx - 3, sy - 3), (sx - 3, sy + 3), (sx + 3, sy - 3), (sx + 3, sy + 3)]
        target = None
        best = None
        for c in corners:
            score = manhattan((ox, oy), c)
            if target is None or score > best:
                target, best = c, score
        return step_toward((sx, sy), target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        best = best_by_distance((sx, sy), targets, "min")
        if best is not None:
            return step_toward((sx, sy), best)
        if ox != sx or oy != sy:
            return step_away((sx, sy), (ox, oy))
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("food") or []
    best = best_by_distance((sx, sy), resources, "min")
    if best is not None:
        return step_toward((sx, sy), best)

    if ox != sx or oy != sy:
        return step_away((sx, sy), (ox, oy))

    grid_w = observation.get("grid_width")
    grid_h = observation.get("grid_height")
    if isinstance(grid_w, int) and isinstance(grid_h, int) and grid_w > 0 and grid_h > 0:
        center = (grid_w // 2, grid_h // 2)
        return step_toward((sx, sy), center)

    return [0, 0]

